44	pub fn compile_test_project(
45	    src: &str,
46	    src_path: &str,
47	    dependencies: Vec<(&str, &str, &str)>,
48	) -> String {
49	    let mut modules = im::HashMap::new();
50	    let ids = UniqueIdGenerator::new();
51	    // DUPE: preludeinsertion
52	    // TODO: Currently we do this here and also in the tests. It would be better
53	    // to have one place where we create all this required state for use in each
54	    // place.
55	    let _ = modules.insert(
56	        PRELUDE_MODULE_NAME.into(),
57	        crate::type_::build_prelude(&ids),
58	    );
59	    let mut direct_dependencies = std::collections::HashMap::from_iter(vec![]);
60	    for (dep_package, dep_name, dep_src) in dependencies {
61	        let mut dep_config = PackageConfig::default();
62	        dep_config.name = dep_package.into();
63	        let parsed = crate::parse::parse_module(
64	            Utf8PathBuf::from("test/path"),
65	            dep_src,
66	            &WarningEmitter::null(),
67	        )
68	        .expect("dep syntax error");
69	        let mut ast = parsed.module;
70	        ast.name = dep_name.into();
71	        let line_numbers = LineNumbers::new(dep_src);
72	
73	        let dep = crate::analyse::ModuleAnalyzerConstructor::<()> {
74	            target: Target::Erlang,
75	            ids: &ids,
76	            origin: Origin::Src,
77	            importable_modules: &modules,
78	            warnings: &TypeWarningEmitter::null(),
79	            direct_dependencies: &std::collections::HashMap::new(),
80	            dev_dependencies: &std::collections::HashSet::new(),
81	            target_support: TargetSupport::NotEnforced,
82	            package_config: &dep_config,
83	        }
84	        .infer_module(ast, line_numbers, "".into())
85	        .expect("should successfully infer dep Erlang");
86	        let _ = modules.insert(dep_name.into(), dep.type_info);
87	        let _ = direct_dependencies.insert(dep_package.into(), ());
88	    }
89	    let path = Utf8PathBuf::from(src_path);
90	    let parsed = crate::parse::parse_module(path.clone(), src, &WarningEmitter::null())
91	        .expect("syntax error");
92	    let mut config = PackageConfig::default();
93	    config.name = "thepackage".into();
94	    let mut ast = parsed.module;
95	    ast.name = "my/mod".into();
96	    let line_numbers = LineNumbers::new(src);
97	    let ast = crate::analyse::ModuleAnalyzerConstructor::<()> {
98	        target: Target::Erlang,
99	        ids: &ids,
100	        origin: Origin::Src,
101	        importable_modules: &modules,
102	        warnings: &TypeWarningEmitter::null(),
103	        direct_dependencies: &direct_dependencies,
104	        dev_dependencies: &std::collections::HashSet::new(),
105	        target_support: TargetSupport::NotEnforced,
106	        package_config: &config,
107	    }
108	    .infer_module(ast, line_numbers, path.clone())
109	    .expect("should successfully infer root Erlang");
110	
111	    let ast = inline::module(ast, &modules);
112	
113	    // After building everything we still need to attach the module comments, to
114	    // do that we're reusing the `attach_doc_and_module_comments` that's used
115	    // for the real thing. We just have to make a placeholder module wrapping
116	    // the parsed ast and call the function!
117	    let mut built_module = build::Module {
118	        name: "my/mod".into(),
119	        code: src.into(),
120	        mtime: SystemTime::UNIX_EPOCH,
121	        input_path: path,
122	        origin: Origin::Src,
123	        ast,
124	        extra: parsed.extra,
125	        dependencies: vec![],
126	    };
127	    let root = Utf8Path::new("/root");
128	    built_module.attach_doc_and_module_comments();
129	
130	    let line_numbers = LineNumbers::new(src);
131	    module(&built_module.ast, &line_numbers, root)
132	        .unwrap()
133	        .replace(
134	            std::include_str!("../../templates/echo.erl"),
135	            "% ...omitted code from `templates/echo.erl`...",
136	        )
137	}
