194	pub fn compile_js(src: &str, deps: Vec<(&str, &str, &str)>) -> String {
195	    let ast = compile(src, deps);
196	    let line_numbers = LineNumbers::new(src);
197	    let stdlib_package = StdlibPackage::Present;
