+        .infer_module(ast, line_numbers, "".into())
+        .expect("should successfully infer");
+        let _ = modules.insert((*dep_name).into(), dep.type_info);
+        let _ = direct_dependencies.insert((*dep_package).into(), ());
+    });
+
